insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 1, 'What does drilling a hole do to the stress field?', '["It relieves it, by removing the loaded material.", "It concentrates it. The load the removed rock carried has to be taken by the rock around the hole.", "It leaves it unchanged, because the stresses are far-field quantities set by burial and tectonics rather than by the wellbore.", "It rotates it, so that one principal direction aligns with the hole axis and the other two lie in its cross section."]'::jsonb, 1, 'A hole is a stress raiser. Drilling one is an act of loading the rock rather than of relieving it.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 2, 'By how much does a circular hole amplify a far-field stress difference?', '["By a factor of three.", "By a factor that depends on the ratio of the two far-field stresses, and which approaches two for a nearly isotropic field.", "Not at all. The hoop stress range at the wall equals the far-field range for a circular opening in an elastic medium.", "By a factor of four in the hoop stress range."]'::jsonb, 3, 'The hoop stress runs from three times the smaller effective stress less the larger, up to three times the larger less the smaller.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 3, 'Name the three wall stresses.', '["Hoop around the circumference, axial along the hole, and radial outward, which is the mud.", "Vertical, maximum horizontal and minimum horizontal.", "Normal, shear and mean, corresponding to the three invariants of the stress tensor evaluated at the surface of the borehole.", "Compressive, tensile and hydrostatic, which are the three modes in which the rock at the wall can be loaded by the mud."]'::jsonb, 0, 'Everything in this tier is those three, evaluated at every angle round the hole and compared against two criteria.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 4, 'What is the radial stress at the wall equal to?', '["The minimum horizontal stress.", "The average of the hoop and axial stresses, which is what the free surface condition at the wall of the hole requires.", "The well pressure less the pore pressure.", "Zero, because the wall is a free surface and no material lies outside it to carry a radial load."]'::jsonb, 2, 'It is the same at every angle round the hole, because the mud does not know which way is up.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 5, 'Why does the hoop stress go through two full cycles in one turn round the hole?', '["Because there are two horizontal stresses.", "Because it depends on the cosine of twice the angle.", "Because the hole is elliptical once a breakout has formed, and the two lobes of the breakout give two maxima each turn.", "Because the shear term reverses sign twice as the angle sweeps through a full circle of three hundred and sixty degrees."]'::jsonb, 1, 'That is why breakouts come in pairs on opposite sides of a hole.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 6, 'Where do breakouts form on a vertical hole?', '["At ninety degrees to the maximum horizontal stress direction, where the hoop stress peaks.", "Along the maximum horizontal stress direction.", "On the high side and the low side, since gravity concentrates the cuttings load there and undercuts the wall over time.", "At the angle where the shear term is largest, which depends on the inclination and cannot be predicted from the stresses alone."]'::jsonb, 0, 'It is the basis of stress-orientation interpretation from calipers and image logs.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 7, 'Where do drilling-induced tensile fractures appear relative to breakouts?', '["In the same place, at the hoop stress peak.", "At forty-five degrees from them, where the shear stress at the wall of the hole reaches its maximum value.", "Randomly, since tensile failure depends on pre-existing flaws rather than on the orientation of the stress field.", "Ninety degrees away, along the maximum horizontal stress direction."]'::jsonb, 3, 'They form at the hoop stress DIP, and seeing both on the same image log constrains the azimuth twice over.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 8, 'What does the mud do to the hoop stress and the radial stress?', '["Raises both of them equally.", "Lowers both of them, since the mud supports the wall from inside and reduces every component of the stress concentration.", "Lowers the hoop one and raises the radial one, both one for one.", "Leaves the hoop stress alone and raises only the radial one, which is why heavy mud helps against collapse but not against fracture."]'::jsonb, 2, 'That is why the Mohr-Coulomb gap closes at one plus q per unit of pressure.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 9, 'Why does the collapse margin improve faster than one unit per unit of mud pressure?', '["Because the largest wall stress falls by one while the smallest rises by one, and the criterion weights the smallest by q.", "Because the mud is denser than the pore fluid.", "Because the radial stress acts over the whole circumference while the hoop stress acts only at the two breakout positions.", "Because raising the mud weight also raises the pore pressure at the wall, which reduces the effective stresses further."]'::jsonb, 0, 'With a friction angle of 32 degrees that is a margin improvement of about 4.25 per unit of pressure.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 10, 'And how fast does the fracture margin worsen?', '["Also at one plus q per unit.", "One for one, with no amplification.", "At q per unit, since the tensile criterion is the mirror image of the shear one and carries the same frictional multiplier.", "Faster than one for one, because the axial stress also falls as the well pressure rises through the Poisson correction."]'::jsonb, 1, 'The window is asymmetric for that reason: heavy mud is strong medicine against collapse and mild poison against fracture.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 11, 'What is the shear term at the wall, and when is it zero?', '["It is always zero at a free surface.", "It is zero whenever the hoop and axial stresses are equal, which happens at two angles on every hole regardless of attitude.", "It is zero when the mud weight equals the minimum horizontal stress, which is the balanced condition at the wall.", "It is zero for a vertical hole in this stress field and non-zero as soon as the hole deviates."]'::jsonb, 3, 'It is the entire difference between a vertical well problem and a deviated one, and it is why a full tensor rotation is needed.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 12, 'How many rotations take the far field into the borehole frame?', '["One, directly from principal to borehole.", "Three, one about each axis, following the standard Euler convention used throughout directional drilling calculations.", "Two: principal into geographic, then geographic into borehole.", "None, because the Kirsch solution is written in the principal frame and applies directly without any rotation at all."]'::jsonb, 2, 'The first is about the vertical by the SHmax azimuth; the second depends on the hole''s inclination and azimuth.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 13, 'Why does a vertical hole have closed-form answers?', '["Because the hole axis is already a principal direction, so the rotated tensor stays diagonal and all shear terms vanish.", "Because there is no azimuth to consider.", "Because the two horizontal stresses are close together, so the hoop stress variation round the hole is small enough to neglect.", "Because the Poisson correction to the axial stress drops out when the hole is aligned with the vertical stress direction."]'::jsonb, 0, 'The hoop stress reduces to the textbook two-dimensional form and both criteria can be solved on paper.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 14, 'What does the mud weight NOT do?', '["Raise the radial stress at the wall.", "Change which angle round the hole fails first.", "Lower the hoop stress at the angle where the breakout would form, since the differential pressure enters that formula directly.", "Affect the fracture initiation pressure, which is set by the far-field stresses and the tensile strength alone."]'::jsonb, 1, 'The peak and the dip stay where the stress field and the trajectory put them. The whole pattern just slides.'),
  ('geomech', 'intermediate', 'module', 'm01-the-hole-in-the-rock', 15, 'Three failure mechanisms look like collapse and ignore the mud weight. Name them.', '["Shear failure at the hoop stress peak.", "Tensile splitting of the wall, which is prevented by keeping the mud weight below the fracture initiation pressure.", "Chemical instability in a reactive shale, bedding-plane slip, and time-dependent creep.", "Breakout widening, which is controlled by raising the mud weight until the Mohr-Coulomb criterion is satisfied everywhere."]'::jsonb, 2, 'All three look like collapse and none responds to mud weight the way this model predicts.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 1, 'What physically happens in a wellbore collapse?', '["The rock at the hoop stress peak fails in shear and pieces spall off the wall.", "The hole closes in under the overburden.", "The formation flows into the wellbore plastically, reducing the hole diameter until the drill string can no longer be moved.", "The wall splits along a plane of weakness and the resulting fragments are carried away by the circulating mud."]'::jsonb, 0, 'It makes the hole BIGGER rather than smaller. A hole that genuinely closes in is creep, which this model does not have.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 2, 'What does a collapse look like at surface?', '["A sudden loss of returns at the flow line.", "An increase in the rate of penetration accompanied by a fall in the standpipe pressure as the annulus opens up.", "Angular cavings on the shakers, an enlarged two-lobed caliper, rising torque and drag.", "A gain in the active pit volume, since the failed material displaces mud from the annulus back into the surface system."]'::jsonb, 2, 'The cavings are larger than the drilled cuttings and have a different shape, which is what distinguishes them.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 3, 'State the Mohr-Coulomb criterion as the engine applies it.', '["The shear stress must not exceed the cohesion.", "The largest effective principal wall stress must not exceed UCS plus q times the smallest.", "The mean effective stress at the wall must stay below the unconfined compressive strength divided by the frictional ratio.", "The difference between the hoop and radial stresses must stay below twice the cohesion of the rock at that depth."]'::jsonb, 1, 'Satisfy it at every angle and no breakout forms. Violate it anywhere and one does.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 4, 'How does the engine find the worst angle?', '["By solving for it analytically.", "By a Newton iteration on the derivative of the margin with respect to angle, started from the vertical-well solution.", "By evaluating only the two angles where the hoop stress is extremal, since the worst margin must occur at one of them.", "By sweeping theta from 0 to 179 degrees in one degree steps."]'::jsonb, 3, 'There is no closed form for the worst angle on a deviated hole, and half a turn is enough because the pattern repeats.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 5, 'What does the one degree theta grid cost?', '["A very slightly optimistic collapse pressure if the true worst angle falls between two grid points.", "Nothing at all.", "A reported breakout angle that can be wrong by up to ninety degrees when the margin has two nearly equal maxima.", "A collapse pressure that is systematically conservative, because the grid always samples a point away from the true peak."]'::jsonb, 0, 'On a smooth function with a broad maximum the error is far below the uncertainty in any input, and the oracle uses the same grid.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 6, 'What physically happens in a tensile wall failure?', '["The rock is crushed by the mud pressure.", "The radial stress exceeds the rock''s tensile strength, which pushes the wall outward and opens a fracture perpendicular to it.", "The hoop stress at its dip is pushed through zero into tension and the wall splits.", "The axial stress falls below zero as the mud pressure lifts the rock above the bit, which splits the hole horizontally."]'::jsonb, 2, 'Rock in tension fails at a very small stress, and the tensile strength is often taken as zero.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 7, 'Which stress does the fracture criterion watch?', '["The radial stress.", "The smallest of the hoop and axial pair, after the shear term is folded in.", "The largest of the three principal wall stresses, since a tensile failure is the mirror image of a shear one.", "The far-field minimum horizontal stress, which is what a fracture must open against once it leaves the wall."]'::jsonb, 1, 'The radial effective stress going negative below balance is a well control condition rather than hydraulic fracturing of the wall.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 8, 'What is fracture initiation NOT?', '["An upper bound on the mud weight.", "A property of the intact rock at the wall, since it depends on the far-field stresses rather than on the material itself.", "A criterion that can be evaluated by bisection, because the least wall stress is not monotone in the well pressure.", "A leak-off test prediction, a propagation pressure, or a lost circulation pressure."]'::jsonb, 3, 'Initiation is generally higher than propagation, and losses usually go into natural fractures well below either.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 9, 'What is the practical consequence of the last point?', '["The upper bound is always conservative.", "The fracture criterion should be replaced by a leak-off test result at every depth, which is what a real study always does.", "A window whose upper bound is fracture initiation is optimistic wherever natural fractures exist.", "The upper bound cannot be computed at all in a fractured formation, so the window has to be quoted as open-ended above."]'::jsonb, 2, 'A conservative upper bound in practice is the minimum horizontal stress, which is usually a good deal lower.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 10, 'What does the zero-breakout-width criterion require?', '["That the Mohr-Coulomb criterion is satisfied at every angle round the hole, so the very first sliver does not fail.", "That no breakout exceeds thirty degrees of width.", "That the breakout, if one forms, is symmetric about the hoop stress peak and therefore does not undercut the wall.", "That the failed material is removed from the annulus faster than it arrives, which is a hole cleaning condition."]'::jsonb, 0, 'It is the pressure at which a breakout would just BEGIN, not the pressure at which the hole becomes unusable.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 11, 'How much conservatism is in that?', '["Very little, a few percent at most.", "A great deal. Breakouts of 30 to 60 degrees are common on wells that were drilled and cased without incident.", "None, because a breakout of any width undercuts the wall and eventually leads to a pack-off if it is allowed to continue.", "It cannot be quantified, because the relationship between breakout width and mud weight is not monotone."]'::jsonb, 1, 'Allowing a 60 degree breakout can lower the required mud weight by a substantial fraction of the collapse gradient.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 12, 'Why does the engine use zero width anyway?', '["Because wider criteria are harder to compute.", "Because a tolerated breakout width would have to be calibrated per field, and the engine has no mechanism for field-specific inputs.", "Because the theta sweep evaluates only one angle at a time and cannot integrate over a failed arc.", "It needs no extra parameter, it is unambiguous, and it errs safe."]'::jsonb, 3, 'Zero width is a definition; forty degrees is a judgement, and a judgement needs data from somewhere.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 13, 'The lower bound on mud weight is which of two candidates?', '["The collapse pressure, always.", "The pore pressure, always, because a kick is a more immediate hazard than a breakout on any well that is being drilled.", "The larger of the collapse pressure and the pore pressure.", "The average of the two, weighted by the fraction of the section in which each of them is the binding constraint."]'::jsonb, 2, 'The mud has to clear both, and a window measured from the smaller would include weights that take a kick.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 14, 'Why can the two candidates swap?', '["Because one depends on the rock''s fluid and the other on the rock''s strength and the hole''s attitude, which are unrelated.", "Because the mud weight changes between sections.", "Because the pore pressure ramp crosses the collapse gradient at a fixed depth in every well, which is the casing point.", "Because the collapse pressure is computed at zero breakout width, and a wider tolerance would put it below the pore pressure."]'::jsonb, 0, 'Nothing forces one to be above the other, and both cases occur in this course''s fixtures.'),
  ('geomech', 'intermediate', 'module', 'm02-the-two-criteria', 15, 'What does the upper bound have that the lower one does not?', '["Two candidates of its own.", "No competition. Fracture initiation is the only candidate the engine considers.", "A closed form for the deviated case, which the collapse criterion lacks because its worst angle has to be found by search.", "A dependence on the friction angle, which is why the fracture gradient moves when the friction angle is swept."]'::jsonb, 1, 'In practice the minimum horizontal stress or a lost circulation pressure is often lower, and the course says so.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 1, 'A vertical hole is run at three different nominal azimuths. What stays the same?', '["Nothing. All three outputs change.", "Only the window width, since the two bounds move together while the difference between them stays constant.", "The collapse pressure, the fracture pressure and the window width, to every digit.", "Only the breakout angle, because it is measured in the borehole frame and the borehole frame does not rotate."]'::jsonb, 2, 'There is no direction to a vertical line, so the azimuth is meaningless.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 2, 'And what changes?', '["The reported breakout angle, because it is measured from a high side that the nominal azimuth defines.", "The collapse pressure, slightly.", "The fracture initiation pressure, which depends on the angle between the hole and the maximum horizontal stress direction.", "Nothing at all, since every output of a vertical hole calculation is independent of the azimuth by construction."]'::jsonb, 0, 'The breakout is in the same PHYSICAL place in all three runs. Only the reference direction moved.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 3, 'How would you check that a stress rotation is implemented correctly?', '["Compare the answer against a leak-off test.", "Add the nominal azimuth to the reported breakout angle on a vertical hole and confirm the bearing is the same every time.", "Run the calculation at two inclinations and confirm the collapse pressure changes smoothly between them without any jumps.", "Verify that the trace of the stress tensor is preserved through the rotation, which is a mathematical invariant."]'::jsonb, 1, 'It is a cheap test that costs nothing to run, and a sign error in a rotation is invisible by inspection.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 4, 'In general, what does deviating a hole do to the window?', '["Always widens it.", "Leaves it unchanged in width while shifting both bounds upward, since the overburden replaces a horizontal stress in the section.", "Narrows it from below only, because the collapse criterion is the one that depends on the hole attitude.", "Usually narrows it, by raising the collapse pressure and lowering the fracture pressure at once."]'::jsonb, 3, 'A deviated hole is loaded by a mixture of a horizontal stress and the overburden, which are further apart than the two horizontals.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 5, 'Does that rule always hold in this course''s fixture?', '["Yes, at every azimuth and inclination.", "Yes, except at exactly ninety degrees of inclination, where the two horizontal stresses drop out of the cross section entirely.", "No. Toward the minimum horizontal stress, a moderate deviation WIDENS the window.", "It cannot be determined, because the fixture does not sweep enough azimuths to establish a trend either way."]'::jsonb, 2, 'At thirty degrees toward Shmin the window is wider than vertical, and it is still wider at sixty.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 6, 'Why does deviating toward the minimum horizontal stress cost so little?', '["Because the overburden replaces the LARGER horizontal stress in the hole''s cross section rather than the smaller one.", "Because the hole is closer to the bedding there.", "Because the shear terms vanish when the hole is aligned with a principal direction, which happens along Shmin.", "Because the pore pressure is lower along that azimuth, which raises the effective stresses and strengthens the rock."]'::jsonb, 0, 'The least hoop stress goes as three times the smaller cross-sectional stress less the larger, so a bigger smaller one helps.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 7, 'Comparing two horizontal holes at the same depth, which direction gives more window?', '["Along the maximum horizontal stress.", "Along the minimum horizontal stress, by about 35 percent in this fixture.", "Neither. A horizontal hole samples both horizontal stresses equally regardless of which direction it is pointed in.", "It depends on the depth: shallow holes prefer one direction and deep holes the other, because the stress ordering changes."]'::jsonb, 1, 'The conventional rule agrees, and it is worth knowing that the rule is regime-dependent rather than universal.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 8, 'Where does most of that difference come from?', '["The collapse end, by a wide margin.", "Both ends equally, since the hoop stress pattern shifts uniformly and both criteria respond to the same shift.", "Neither end. The difference comes from the pore pressure, which sets the lower bound in both cases.", "The fracture end. The two collapse pressures differ by far less than the two fracture pressures."]'::jsonb, 3, 'Drilling along Shmin puts the larger horizontal stress in the section, which raises the least hoop stress.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 9, 'What does hydraulic fracturing want from the trajectory, and does it agree?', '["Transverse fractures, which need a well along Shmin, so on this fixture the two objectives happen to agree.", "Longitudinal fractures, which need a well along Shmin.", "Nothing in particular, since fracture orientation is set by the far-field stresses and not by the wellbore direction.", "A vertical well, since only a vertical well produces fractures in a predictable plane relative to the reservoir."]'::jsonb, 0, 'They can point the same way or opposite ways, and the well plan has to decide which matters more.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 10, 'What happens to the breakout angle as a hole is laid over toward north in this fixture?', '["It stays fixed at 90 degrees.", "It jumps discontinuously at about forty-five degrees of inclination, where the axial stress overtakes the hoop stress.", "It walks steadily from 150 degrees round to 90 as the inclination rises.", "It rotates by exactly the inclination, so a sixty degree hole has a breakout sixty degrees from its vertical position."]'::jsonb, 2, 'On a horizontal hole a breakout at 90 degrees from the high side is on the FLANK rather than the roof.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 11, 'Why does where the breakout sits matter operationally?', '["Because it determines the caliper reading.", "Because material spalling from the roof falls into the hole and material from the flanks forms a bed on the low side.", "Because a breakout on the high side is invisible to a four-arm caliper, which only measures across the two orthogonal axes.", "Because a flank breakout weakens the hole against collapse under the weight of the drill string lying on the low side."]'::jsonb, 1, 'The hole cleaning problem and the stability problem interact, and where the failure is determines how.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 12, 'What is the interpretation trap on a deviated well?', '["Breakouts do not form on deviated wells.", "The caliper cannot distinguish a breakout from a keyseat on a deviated well, so the orientation cannot be measured at all.", "The breakout always forms on the low side of a deviated well, so the orientation carries no stress information.", "A breakout orientation there does not directly give the minimum horizontal stress direction."]'::jsonb, 3, 'Recovering a stress azimuth from it needs the full rotation, the inclination, the azimuth and a stress magnitude model.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 13, 'What is the trajectory deliverable this module argues for?', '["A map of window width against inclination and azimuth at the critical depths, with the plan marked on it.", "A single recommended azimuth.", "A ranking of the candidate trajectories by total measured depth, since that is the main driver of the cost of the well.", "A recommendation to drill vertical wherever the target permits it, since vertical is the widest window at every depth."]'::jsonb, 0, 'A planner looking at that map can see whether the plan is on a ridge or in a valley, and how much freedom there is.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 14, 'What constraints does that map NOT contain?', '["The stress azimuth uncertainty.", "The pore pressure, which is a separate deliverable and is not part of the geomechanics contribution to a well plan.", "Anti-collision, target tolerance, dogleg limits, casing wear, torque and drag, and the surface location.", "The rock strength, which comes from the log analyst rather than from the geomechanics workflow itself."]'::jsonb, 2, 'Geomechanics supplies one input to a decision with many, and its job is to make its own contribution legible.'),
  ('geomech', 'intermediate', 'module', 'm03-what-the-hole-attitude-costs', 15, 'Where does the trajectory argument matter most?', '["On wells with a wide window and a simple target.", "Where the window is already narrow: deepwater, depleted reservoirs, and fields with a stuck pipe history.", "On exploration wells, where the stress field is least known and therefore the trajectory choice carries the most uncertainty.", "On vertical wells, where the azimuth is the only remaining degree of freedom available to the well planner."]'::jsonb, 1, 'A well with 500 kg/m3 of window can afford to lose a third of it. One with 100 cannot.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 1, 'Where did the expected values in the golden file come from?', '["Field measurements from a set of offset wells.", "An independent numpy implementation of the same specification.", "The engine itself, recorded once at a version that had been reviewed and signed off by a second geomechanics engineer.", "Published worked examples from the rock mechanics literature, transcribed and converted into SI units for the file."]'::jsonb, 1, 'Same rotations, same Kirsch formulas, same criterion, same bisections on the same grid.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 2, 'What does agreement with an independent implementation catch?', '["Errors in the underlying physics.", "Parameters taken from a lithology table rather than from a measurement, since a second implementation would use different defaults.", "Cases where the model is being applied outside the range of conditions it was designed and calibrated for.", "Transcription errors, convention drift and numerical specification differences."]'::jsonb, 3, 'A sign error in a rotation is easy to make and invisible by inspection, and two implementations will disagree on it.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 3, 'What does it NOT catch?', '["A wrong equation, wrong parameters, or a model that does not describe the earth.", "A sign error in a rotation.", "A convention mismatch, such as measuring theta from north rather than from the high side of the borehole.", "A difference in the number of bisection steps, which would show up in the last digits of every comparison."]'::jsonb, 0, 'If the equations are wrong, both implementations are wrong together and the comparison is silent.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 4, 'Distinguish verification from validation.', '["They are two words for the same activity.", "Verification is done by the developer and validation by the user, but both compare the same outputs against the same references.", "Verification asks whether the equations were solved correctly; validation asks whether they describe the world.", "Verification uses synthetic data and validation uses field data, and both establish that the model is fit for purpose."]'::jsonb, 2, 'Two independent implementations agreeing is strong verification and no validation at all.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 5, 'What are the vertical fixture''s inputs chosen for?', '["Realism, matching a typical North Sea well.", "Round numbers, so every intermediate result is checkable by hand.", "The most severe stress state the engine can handle, so that the fixture exercises the numerical routines at their limits.", "Consistency with the profile, so that the fixture and the main cases can be compared directly against each other."]'::jsonb, 1, 'It is chosen for arithmetic rather than for realism, and SHmax exceeds the overburden in it, which is not normal faulting.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 6, 'How closely does the engine reproduce the vertical closed forms?', '["Exactly. Not close: identical, to the last digit, on both pressures.", "To within a relative tolerance of 1e-6.", "To within a few pascals, which is the accumulated rounding error of the sixty bisection steps the engine runs.", "To within one degree on the breakout angle and one percent on the two pressures, which is the stated acceptance."]'::jsonb, 0, 'A closed form says the program agrees with the mathematics rather than with another program.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 7, 'Write the closed-form collapse pressure for a vertical hole.', '["The pore pressure plus UCS divided by q.", "Three times the effective Shmin less the effective SHmax, less the unconfined compressive strength, plus the pore pressure.", "The effective overburden divided by the frictional ratio, plus the pore pressure and the unconfined compressive strength.", "The pore pressure plus three times the effective SHmax less the effective Shmin less UCS, all over one plus q."]'::jsonb, 3, 'One plus q in the denominator is the amplification: the largest wall stress falls by one and the smallest rises by one.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 8, 'And the pressure at which that same hole would split in tension?', '["The minimum horizontal stress plus the tensile strength.", "The pore pressure plus three times the effective SHmax less the effective Shmin, divided by one plus the frictional ratio.", "The pore pressure plus three times the effective Shmin less the effective SHmax, plus the tensile strength.", "The overburden less the pore pressure, multiplied by the ratio of horizontal to vertical effective stress."]'::jsonb, 2, 'No amplification here: the least wall stress falls one for one with the well pressure.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 9, 'Why does the collapse form have one plus q and the fracture form does not?', '["Because collapse is a shear failure.", "Because the collapse criterion involves both the largest and the smallest wall stress, and the fracture one involves only the least.", "Because the friction angle enters the tensile criterion through the tensile strength rather than through the frictional ratio.", "Because the fracture criterion is evaluated at a different angle round the hole, where the amplification happens to be one."]'::jsonb, 1, 'Raising the pressure moves two stresses toward each other in the first case and one stress in the second.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 10, 'Where in the vertical fixture does the breakout form, and what does that confirm?', '["At ninety degrees from the high side, which is along Shmin, and it confirms the convention as well as the numbers.", "Along SHmax, at zero degrees.", "At forty-five degrees from the high side, where the shear stress at the wall of the hole reaches its maximum value.", "At the angle where the axial stress is largest, which for a vertical hole is at the maximum horizontal stress direction."]'::jsonb, 0, 'The nominal azimuth and the SHmax azimuth are both zero in the fixture, so the high side is along SHmax.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 11, 'When should the vertical fixture be run?', '["Once, at the start of the project.", "Only when a discrepancy is found between the engine and the golden file, as a way of deciding which of the two is wrong.", "Never in production, since it is a synthetic case whose parameters do not correspond to any real formation.", "Whenever the engine changes."]'::jsonb, 3, 'It costs nothing and it is the fastest way to find out that a rotation, a sort or a bisection has broken.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 12, 'What would validation of this model actually need?', '["More golden files at more conditions.", "A third independent implementation, so that a majority vote can resolve any disagreement between the first two.", "Caliper data, loss data, and stuck pipe or caving events from a set of offset wells.", "A finer theta grid and more bisection steps, so that the numerical error falls below the physical uncertainty."]'::jsonb, 2, 'Where did breakouts form and how wide, where were returns lost and at what circulating density, and where did the hole give trouble.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 13, 'What is this course''s stated validation status?', '["Fully validated against North Sea field data.", "Verified twice and not validated, because the fixture is synthetic and contains no field data.", "Validated for vertical wells through the closed-form fixture, and verified only for deviated wells against the numpy oracle.", "Unvalidated and unverified, since the golden file was produced by the same author as the engine it is meant to check."]'::jsonb, 1, 'The engine''s own header says the same, and a course claiming more would claim what the file cannot support.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 14, 'What is the profile in the golden file?', '["Synthetic: a constant overburden gradient, a clean pore pressure ramp and a linearly falling sonic curve.", "A real well from the North Sea.", "An average of several offset wells in the same field, resampled onto a common depth grid at fifty metre intervals.", "A worst-case profile constructed to exercise the frictional clamping and the window closure logic at the same time."]'::jsonb, 0, 'Its job is to make every effect attributable to one cause. It is a fixture rather than a well.'),
  ('geomech', 'intermediate', 'module', 'm04-against-the-oracle', 15, 'What three questions should you ask of any geomechanics output you are handed?', '["Which engine, which version, which author.", "What the mud weight was, what the hole size was, and how long the section took to drill from shoe to shoe.", "Whether the stresses are total or effective, whether the depths are measured or true vertical, and what the units are.", "Was it verified, was it validated, and what was it calibrated against on this field?"]'::jsonb, 3, 'The three answers are usually yes, no, and nothing, and knowing that is more useful than the number.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 1, 'Why does the fracture bisection need no scan?', '["Because it converges in fewer steps.", "Because the tensile criterion is linear in the well pressure, which means the answer can be obtained in a single step.", "Because the least wall stress falls monotonically with the well pressure, so there is exactly one crossing.", "Because the fracture pressure is always above the collapse pressure, so the search range can be bracketed in advance."]'::jsonb, 2, 'Eighty bisection steps between zero and an upper limit, and the answer is converged far beyond any meaningful precision.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 2, 'Why does the collapse search need one?', '["Because the worst Mohr-Coulomb margin is not monotone in the well pressure.", "Because the theta sweep is expensive.", "Because the collapse pressure can be zero, and a bisection cannot bracket a root that lies at the edge of its range.", "Because the margin is discontinuous at the angle where the breakout forms, which a bisection would step over."]'::jsonb, 0, 'A naive bisection on a non-monotone function can converge on the wrong root.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 3, 'Why does the margin stop falling as the well pressure rises?', '["Because the rock strength increases with pressure.", "Because the radial stress eventually becomes the LARGEST wall stress, so raising the pressure opens the gap again.", "Because the hoop stress cannot fall below the tensile strength, at which point the fracture criterion takes over from the shear one.", "Because the theta sweep finds a different worst angle, and the margin at that angle behaves differently with pressure."]'::jsonb, 1, 'Past the crossing the roles swap: the radial stress is sigma1 and the hoop stress is sigma3.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 4, 'What would a naive bisection report if it converged on the second crossing?', '["A collapse pressure of zero.", "A collapse pressure that is too low by a small margin, which would be absorbed by the operational safety factor anyway.", "The correct answer, since both crossings satisfy the criterion and either is a valid stabilising pressure.", "A collapse pressure above the fracture pressure, and therefore a section that appears undrillable."]'::jsonb, 3, 'A spectacular wrong answer from a subtle numerical assumption, which is why the engine scans first.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 5, 'Why does the engine use a fixed number of bisection steps rather than a tolerance?', '["Speed. A fixed count is faster than a test.", "Accuracy. A fixed count converges further than a tolerance-based loop, which stops as soon as the criterion is met.", "Reproducibility. A fixed count gives the same bits every time.", "Robustness. A tolerance-based loop can fail to terminate when the function is flat near the root being sought."]'::jsonb, 2, 'That is what lets the independent oracle comparison be meaningful at 1e-9 rather than at 1e-6.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 6, 'What does the 400-step scan resolution cost?', '["If a crossing and an un-crossing both fall inside one interval, the scan misses the pair.", "A small error in the collapse pressure.", "A breakout angle that is quantised to the scan resolution rather than to the one degree theta grid used elsewhere.", "Nothing, because the bisection that follows refines the answer to full precision regardless of the scan spacing."]'::jsonb, 0, 'It is a stated specification rather than a bug, and the oracle mirrors it exactly.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 7, 'What does a collapse pressure of zero mean?', '["The calculation failed to converge.", "The criterion is already satisfied with an empty hole, so collapse is not binding at that depth at all.", "The rock has no strength there, so any mud weight at all will cause the wall to fail immediately upon exposure.", "The pore pressure and the collapse pressure are equal, so the engine reports the difference between them rather than the value."]'::jsonb, 1, 'Reading it as very strong rock is right. Reading it as a mud weight to use is not.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 8, 'Now suppose the engine returns the very top of its bracket instead. Interpretation?', '["The rock is extremely strong.", "The search range was set too low and the calculation should be repeated with a wider bracket around the expected value.", "The collapse and fracture pressures coincide, which is the definition of a marginally stable wellbore.", "No pressure in range stabilises the hole, so the window has closed at that depth."]'::jsonb, 3, 'It is a flag rather than a pressure to use.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 9, 'How do you recognise a clamped stress in a report?', '["A stress larger than the overburden.", "A stress quoted to fewer significant figures than the others, since the clamping routine rounds to the bound value.", "Two stresses exactly equal, or one sitting exactly on a computed bound.", "A negative effective stress, which is the condition the frictional bounds exist to prevent from arising."]'::jsonb, 2, 'Two stresses agreeing exactly is almost never physical.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 10, 'How do you recognise a zero collapse pressure in an equivalent mud weight table?', '["A value far below the density of water, which is the numerical residue of a zero divided by g times depth.", "A value of exactly zero.", "A blank cell, since the engine returns a null rather than a number when the criterion is satisfied at zero pressure.", "A value equal to the pore pressure gradient, since the engine substitutes the lower bound when collapse does not bind."]'::jsonb, 0, 'Both wells'' shallowest checkpoints report such a value, and it means the collapse criterion is not a constraint there.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 11, 'What does the mud window walk do if the lower bound exceeds the upper one?', '["Stops the walk at that depth.", "Records the shallowest such depth and returns a warning naming it.", "Substitutes the fracture gradient for the lower bound, which produces a zero-width window rather than a negative one.", "Reports a negative window width and continues, leaving the interpretation entirely to the reader of the output."]'::jsonb, 1, 'Neither well in this course triggers it at either parameter set.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 12, 'What is the first of the five checks on a stability answer?', '["Is the answer sensitive to the Poisson ratio?", "Does the vertical closed form agree, which is the cheapest of the five to run and therefore belongs first in the sequence?", "Is the lower bound the pore pressure or the collapse pressure, since that decides which of the later checks are relevant?", "Is the window positive?"]'::jsonb, 3, 'If it is not, the model says the section cannot be drilled, and that needs discussing before anything else.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 13, 'Why does the order of the five checks matter?', '["Because the checks depend on each other''s results.", "Because the engine evaluates them in that order internally, so running them differently gives inconsistent intermediate values.", "Because each is cheaper than the one after it, and each that fails makes the later ones pointless.", "Because a report must present them in a standard order for the results to be comparable between wells."]'::jsonb, 2, 'There is no value in a sensitivity study on a window that is negative because of a sign error.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 14, 'What does a good stability report contain beyond the two bounds?', '["Both lower-bound candidates separately, the clamp count, the quality score, and a sensitivity band.", "The engine version and the run date.", "A three-dimensional visualisation of the stress state at the wall, which makes the failure mechanism visible to a reader.", "The full theta sweep at the tightest depth, so that the breakout width can be estimated from the margin profile."]'::jsonb, 0, 'Six columns rather than two, and the difference between a number and a usable number.'),
  ('geomech', 'intermediate', 'module', 'm05-reading-a-stability-answer', 15, 'What should you do when you cannot run the checks?', '["Use a larger safety factor instead.", "Say so. A gradient used without them is being taken on trust, and recording that is more useful than pretending.", "Refuse to use the number, since an unchecked geomechanics output is more dangerous than having no model at all.", "Run the engine a second time with the same inputs, which at least confirms the result is reproducible."]'::jsonb, 1, 'Recording the limitation is a cheap and honest substitute for the check itself.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Give the Professional tier in one claim.', '["The mud weight is bounded below by shear failure or the pore pressure, and above by tension at the wall.", "A hole is a stress raiser.", "The Kirsch solution gives the stresses at the wall of a circular opening as a function of the angle round the circumference.", "Two independent implementations of the same specification agreeing is verification and not validation of the model."]'::jsonb, 0, 'And every one of those three depends on where the hole is pointing.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Which parameter set does the Professional capstone use?', '["The published parameter set from the lessons.", "A third set, different again from both the published values and the ones the Associate tier was graded on.", "The Associate capstone''s, unchanged.", "One the learner selects, since the capstone grades the method rather than a particular numerical outcome."]'::jsonb, 2, 'So if you did that tier, you already have the two horizontal stresses this run needs.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'What hole attitude does it run?', '["Vertical, so the closed forms apply.", "An inclination and an azimuth that are neither of them in the lesson sweeps.", "Horizontal along the minimum horizontal stress, which is the most favourable case and therefore the easiest to check.", "The attitude of the slant well at its tightest point, which links the capstone to the Expert tier''s walk."]'::jsonb, 1, 'The lessons run four inclinations and three azimuths, and the capstone uses none of them.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'For the rock strength at the graded depth, what value goes in?', '["The profile''s published UCS at that depth.", "The McNally value for the same reading, since the section is a sandstone and McNally is the sandstone correlation.", "The lower of the two correlations at that reading, which is the conservative choice for a stability calculation.", "The Horsrud value for the core plug reading, which is the Associate capstone''s own field."]'::jsonb, 3, 'The profile''s published column came from the profile''s own sonic sample, and the capstone uses a core plug instead.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'What is the free check across the six fields?', '["The collapse equivalent mud weight plus the window width must equal the fracture equivalent mud weight exactly.", "The two pressures must sum to the overburden.", "The breakout angle must equal ninety degrees less the inclination, which is the relationship for a hole in a normal faulting field.", "The window width in equivalent mud weight must equal the pressure difference divided by the measured depth at that station."]'::jsonb, 0, 'They are the same three numbers divided by the same denominator. If they do not close, one used a different depth.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Which field is an angle in the borehole frame rather than a compass bearing?', '["The azimuth of the hole.", "The window width, which is expressed as an angle in the stress space rather than as a mud weight in kilograms per cubic metre.", "The breakout angle.", "None of them. All six graded fields are pressures or equivalent mud weights."]'::jsonb, 2, 'It is measured from the high side of the hole, and converting it to a bearing needs the inclination and the azimuth.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Why does the Biot coefficient of 0.9 matter in this tier as well?', '["Because it changes the pore pressure.", "Because it enters the effective stresses at the wall, not just the stress model.", "Because it appears in the Mohr-Coulomb criterion as a multiplier on the frictional ratio, which alters the collapse pressure.", "Because it scales the tensile strength, so a value below one raises the fracture initiation pressure proportionally."]'::jsonb, 1, 'Every stress in the failure criteria is an effective stress, and the Biot coefficient is in the definition of one.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'What did this tier take from the Associate one?', '["The mud window along the trajectory.", "The quality score and the clamp count, which are used to weight the confidence placed in the stability answer.", "The two failure criteria, which were introduced in the Associate tier and applied for the first time in this one.", "Four stresses and a strength at every depth, and nothing else."]'::jsonb, 3, 'This tier is pure mechanics on the previous tier''s model, so an error there propagates through here silently.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'What does it hand to the Expert tier?', '["A calibrated stress model.", "The vertical closed forms, which the Expert tier uses as its check on every station along both of the two wells.", "A stability answer at one depth for one attitude, which the Expert tier walks along a whole trajectory.", "The tightest point on each well, which the Expert tier then uses to design the mud programme per section."]'::jsonb, 2, 'That walk is where the two wells in this course finally separate.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Which habit does the tier name about near-vertical holes?', '["Assume the azimuth does not matter.", "Compute the vertical closed form as a check. It costs two lines and catches conventions, signs and units.", "Run the calculation at several azimuths, since a near-vertical hole is the case where the azimuth dependence is strongest.", "Use a coarser theta grid, since the hoop stress pattern on a vertical hole is smooth and needs fewer sample points."]'::jsonb, 1, 'On a vertical hole they should match exactly and on a hole up to about fifteen degrees they should be close.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Which habit does it name about the lower bound?', '["Ask which of the two candidates produced it, because they have different remedies.", "Always use the pore pressure.", "Add a fixed safety margin to whichever candidate is larger, since both carry a comparable amount of uncertainty.", "Quote it in pascals rather than equivalent mud weight, so that the depth at which it applies cannot be lost."]'::jsonb, 0, 'A maximum of the two hides which, and with it the lever, the uncertainty and the failure mode.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'And what should be remembered whenever a shear failure pressure is quoted?', '["Treat it as a hard operational limit.", "Round it up to the nearest fifty kilograms per cubic metre, which is the resolution at which mud weight is actually controlled.", "Compare it against the pore pressure and report only the larger, since that is the number the driller acts on.", "Treat it as a zero-breakout-width number, which is the pressure at which a breakout begins."]'::jsonb, 3, 'It is not the pressure at which the hole fails, and the difference is large.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'What is the trap in reading a capstone answer at the wrong depth?', '["Nothing, since the fields are pressures.", "The breakout angle changes, since the stress ratio at the wall depends on the depth through the effective stresses.", "The equivalent mud weight fields divide by the depth, so a wrong depth moves three of the six at once.", "The stresses come from a different profile sample, which changes the two pressure fields but leaves the ratios intact."]'::jsonb, 2, 'That is exactly what the free check detects: if the three do not close, one was computed at a different depth.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'What should you predict before running the capstone attitude?', '["What the vertical closed forms would give at that depth on the capstone parameters.", "What the breakout angle will be.", "Which of the two lower-bound candidates will win, since that determines whether the collapse field is the binding number.", "How many bisection steps the engine will need, which indicates whether the answer is well conditioned at that attitude."]'::jsonb, 0, 'Then run the real attitude and say by how much each moved and in which direction.'),
  ('geomech', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What does the Expert tier add that this one does not have?', '["A second failure criterion.", "The trajectory, the sensitivities, the comparison against the other drilling courses, and a full statement of what is missing.", "A treatment of anisotropy and time dependence, which are the two largest omissions from the mechanics used in this tier.", "A calibration of the model against caliper and loss data from the offset wells in the same field."]'::jsonb, 1, 'The list of omissions is longer than in any tier so far, and stating it is what makes the rest usable.'),
  ('geomech', 'intermediate', 'final', null, 1, 'A trainee says drilling a hole relieves the stress in the rock. Correct them.', '["It concentrates it. The load the removed rock carried is taken by the rock around the hole.", "They are right, that is what a free surface does.", "It rotates the stress field so that one principal direction lies along the hole axis, without changing the magnitudes.", "It leaves the field unchanged, since the stresses are far-field quantities set by burial rather than by the wellbore."]'::jsonb, 0, 'A hole is a stress raiser, and drilling one is an act of loading the rock.'),
  ('geomech', 'intermediate', 'final', null, 2, 'The two horizontal stresses at a depth differ by a few megapascals. What does the wall see?', '["The same range, since stress is conserved.", "A range three times as wide, which is the classic stress concentration factor for a circular hole in an elastic medium.", "A hoop stress range four times as wide as the far-field difference.", "A range that depends on the ratio of the two stresses rather than on their difference, approaching zero as they converge."]'::jsonb, 2, 'The hoop stress runs from three times the smaller effective stress less the larger, up to three times the larger less the smaller.'),
  ('geomech', 'intermediate', 'final', null, 3, 'Name the three stresses at the wall of a hole.', '["Vertical, maximum horizontal, minimum horizontal.", "Hoop, axial and radial.", "Normal, shear and mean, being the three quantities the Kirsch formulas evaluate at each angle round the circumference.", "Compressive, tensile and hydrostatic, corresponding to the three modes in which the mud can load the wall of the hole."]'::jsonb, 1, 'The radial one IS the mud, and it is the only thing under anybody''s control at the time of drilling.'),
  ('geomech', 'intermediate', 'final', null, 4, 'Why do breakouts appear as a pair on opposite sides of a hole?', '["Because the caliper has two arms.", "Because the drill string lies against one side of the hole and undercuts the wall symmetrically as it rotates.", "Because the two horizontal stresses each produce their own breakout, one on each side of the wellbore.", "Because the hoop stress depends on the cosine of twice the angle, so it peaks twice in one turn."]'::jsonb, 3, 'Two maxima and two minima round the hole, and the breakouts sit at the maxima.'),
  ('geomech', 'intermediate', 'final', null, 5, 'On a vertical hole, breakouts tell you the direction of which stress?', '["The maximum horizontal stress.", "The overburden, since a vertical hole is aligned with it and the breakout forms in the plane perpendicular to the axis.", "The minimum horizontal stress.", "Neither. Breakout orientation is controlled by the rock fabric rather than by the far-field stress directions."]'::jsonb, 2, 'They form at ninety degrees to SHmax, and drilling-induced tensile fractures form ninety degrees from them.'),
  ('geomech', 'intermediate', 'final', null, 6, 'Raising the mud weight does two things to the wall stresses. What?', '["Lowers the hoop stress and raises the radial stress, both one for one.", "Raises both of them.", "Lowers both, since the mud supports the wall and reduces every component of the stress concentration around it.", "Raises the radial stress only, which is why heavy mud helps against collapse but does nothing about tensile failure."]'::jsonb, 0, 'That is why the Mohr-Coulomb gap closes at one plus q per unit of pressure.'),
  ('geomech', 'intermediate', 'final', null, 7, 'The collapse margin improves faster than the fracture margin worsens. Why?', '["Because the collapse criterion has a strength term.", "Because collapse involves both the largest and smallest wall stress and fracture involves only the least.", "Because the fracture criterion is evaluated at a different angle, where the pressure sensitivity of the hoop stress is smaller.", "Because the tensile strength is small compared with the unconfined compressive strength in every rock in the profile."]'::jsonb, 1, 'One plus q per unit against one per unit, which makes the window asymmetric.'),
  ('geomech', 'intermediate', 'final', null, 8, 'What is zero for a vertical hole and non-zero the moment it deviates?', '["The axial stress.", "The Poisson correction to the axial stress, which vanishes when the hole is aligned with a principal stress direction.", "The radial stress, which is the mud pressure less the pore pressure and depends on the hole''s attitude through the depth.", "The shear term at the wall."]'::jsonb, 3, 'It is the entire difference between the vertical and deviated problems, and why a full tensor rotation is needed.'),
  ('geomech', 'intermediate', 'final', null, 9, 'Getting a stress tensor out of the earth frame and into the hole frame takes what?', '["One, by the hole inclination.", "Three, following the standard Euler convention with rotations about each of the three coordinate axes in turn.", "Two: about the vertical by the SHmax azimuth, then into the hole''s own frame.", "None. The Kirsch solution is written in the principal frame and needs no rotation at any hole attitude."]'::jsonb, 2, 'The second depends on the inclination and azimuth, and it is where the shear terms come from.'),
  ('geomech', 'intermediate', 'final', null, 10, 'A caving arrives on the shaker. How do you know it is not a cutting?', '["It is larger and angular, with a different shape.", "It is heavier than a cutting.", "It arrives at a different point in the circulation, since a caving comes from the wall rather than from the bit face.", "It is coated in filter cake, which a cutting produced at the bit face never has time to develop."]'::jsonb, 0, 'Cavings, a two-lobed caliper, rising torque and drag, and eventually a pack-off.'),
  ('geomech', 'intermediate', 'final', null, 11, 'Write down the shear failure condition the code actually tests at each angle.', '["The shear stress must not exceed the cohesion.", "The largest effective principal wall stress must not exceed UCS plus q times the smallest.", "The mean effective wall stress must remain below the unconfined compressive strength divided by the frictional ratio.", "The difference between the hoop and radial stresses must stay below twice the cohesion at that depth."]'::jsonb, 1, 'Satisfied at every angle means no breakout. Violated anywhere means one forms.'),
  ('geomech', 'intermediate', 'final', null, 12, 'Why does the engine sweep theta rather than solve for the worst angle?', '["Because a sweep is faster than a solve.", "Because the worst angle can lie anywhere and the margin has several local maxima, so a solve would need many starting points.", "Because the theta grid is used by the oracle, and matching it exactly is required for the comparison to be meaningful.", "Because there is no closed form for it on a deviated hole."]'::jsonb, 3, 'The shear term moves it, and finding it analytically means solving a transcendental equation.'),
  ('geomech', 'intermediate', 'final', null, 13, 'Describe what the rock does when the mud is too heavy.', '["The rock crushed by the mud pressure.", "The radial stress exceeding the tensile strength, which pushes the wall outward and opens a fracture normal to it.", "The hoop stress at its dip pushed through zero into tension, splitting the wall.", "The axial stress dropping below zero, which parts the rock along a plane perpendicular to the hole axis."]'::jsonb, 2, 'Rock is weak in tension, and the tensile strength is often taken as zero.'),
  ('geomech', 'intermediate', 'final', null, 14, 'A fracture initiation pressure is NOT which three things?', '["A leak-off test prediction, a fracture propagation pressure, or a lost circulation pressure.", "An upper bound on the mud weight.", "A wellbore stability limit, since it concerns the intact rock at the wall rather than the mud weight the hole can carry.", "A quantity that depends on the tensile strength, which is usually taken as zero and therefore drops out of the criterion."]'::jsonb, 0, 'Initiation is generally higher than propagation, and losses usually go into natural fractures well below either.'),
  ('geomech', 'intermediate', 'final', null, 15, 'In a naturally fractured formation, what should the upper bound be instead?', '["The fracture initiation pressure, unchanged.", "The minimum horizontal stress, or a measured loss pressure.", "The overburden gradient, since a fracture cannot propagate against a stress larger than the vertical one in a normal regime.", "The pore pressure plus the tensile strength, which is the pressure at which a pre-existing fracture would first open."]'::jsonb, 1, 'A hole meeting a natural fracture does not have to split anything: it only has to open a plane that already exists.'),
  ('geomech', 'intermediate', 'final', null, 16, 'The engine''s collapse criterion requires zero breakout width. What does that mean?', '["It means no breakout can ever form.", "It means the criterion is evaluated only at the hoop stress peak, rather than integrated over the arc of failed material.", "It means the reported pressure includes an allowance for a breakout of the width typically tolerated in the field.", "It is the pressure at which a breakout would just begin, not the pressure at which the hole becomes unusable."]'::jsonb, 3, 'Breakouts of 30 to 60 degrees are common on wells that were drilled and cased without incident.'),
  ('geomech', 'intermediate', 'final', null, 17, 'Why does the engine choose the strictest possible collapse criterion?', '["Because a wider criterion is harder to compute.", "Because the theta sweep cannot integrate over an arc, so a width-based criterion is not implementable in the current scheme.", "It needs no extra parameter, it is unambiguous, and it errs safe.", "Because field data on tolerated breakout width is proprietary and cannot be embedded in a general purpose engine."]'::jsonb, 2, 'Zero width is a definition; forty degrees is a judgement that needs calibration data from somewhere.'),
  ('geomech', 'intermediate', 'final', null, 18, 'Two unrelated failures compete to set the floor. Name them and say how they combine.', '["The collapse pressure and the pore pressure.", "The collapse pressure and the tensile strength.", "The pore pressure and the minimum horizontal stress, which together bound the range in which a hole can be held open.", "The fracture initiation pressure and the equivalent circulating density, whichever of the two is reached first."]'::jsonb, 0, 'The mud has to clear both, and which one wins changes with depth.'),
  ('geomech', 'intermediate', 'final', null, 19, 'Explain how a section can be limited by well control at one depth and by stability at another.', '["Because the mud weight changes between sections.", "Because one is a property of the rock''s fluid and the other of its strength and the hole''s attitude.", "Because the pore pressure ramp always crosses the collapse gradient at some depth, which is what sets the casing point.", "Because the collapse gradient is computed at zero breakout width, and a wider tolerance would always put it lower."]'::jsonb, 1, 'Nothing forces one above the other, and both cases occur in the two wells of this course.'),
  ('geomech', 'intermediate', 'final', null, 20, 'Three runs, straight down, at bearings 000, 060 and 150. Which numbers agree?', '["Only the breakout angle.", "None of them, since the nominal azimuth enters the rotation and therefore changes every quantity the engine computes.", "All of them including the breakout angle, since a vertical hole has no preferred direction of any kind.", "The two pressures and the window width, to every digit."]'::jsonb, 3, 'There is no direction to a vertical line. Only the breakout angle changes, because its reference direction moved.'),
  ('geomech', 'intermediate', 'final', null, 21, 'How does that give you a free check on a stress rotation?', '["Compare the answer against a leak-off test.", "Confirm the trace of the rotated stress tensor equals the trace of the original, which is preserved by any rotation.", "Add the nominal azimuth to the reported breakout angle and the bearing should be the same in every run.", "Run the same case at two inclinations and check the collapse pressure changes smoothly with no discontinuity."]'::jsonb, 2, 'A sign error in a rotation is invisible by inspection, and this test costs nothing.'),
  ('geomech', 'intermediate', 'final', null, 22, 'Does deviating a hole always narrow the window?', '["No. Toward the minimum horizontal stress a moderate deviation widens it in this fixture.", "Yes, at every azimuth and inclination.", "Yes, except for a vertical hole, where the window is the same at every azimuth and therefore cannot be narrowed further.", "It cannot be established, because the fixture sweeps too few azimuths to distinguish a trend from numerical noise."]'::jsonb, 0, 'At thirty degrees toward Shmin the window is wider than vertical, and still wider at sixty.'),
  ('geomech', 'intermediate', 'final', null, 23, 'A horizontal well can be drilled along either horizontal stress direction. Which gives more window?', '["Along the maximum horizontal stress.", "Along the minimum horizontal stress, by about a third in this fixture.", "Neither. A horizontal hole samples both horizontal stresses regardless of the direction it is pointed in.", "It depends on the depth, because the stress ordering changes between the shallow and the deep parts of the section."]'::jsonb, 1, 'The conventional rule agrees, and the rule is regime-dependent rather than universal.'),
  ('geomech', 'intermediate', 'final', null, 24, 'Break that gain down: is it the shear end or the tension end doing the work?', '["The collapse end.", "Both ends equally, since the hoop stress pattern shifts uniformly and both criteria respond to the same shift.", "The pore pressure, which sets the lower bound in both cases and therefore cancels out of the comparison.", "The fracture end."]'::jsonb, 3, 'Drilling along Shmin puts the larger horizontal stress in the cross section, which raises the least hoop stress.'),
  ('geomech', 'intermediate', 'final', null, 25, 'Which stress direction does hydraulic fracturing prefer a horizontal well to run along?', '["The maximum horizontal stress.", "Neither. Fracture orientation depends on the far-field stresses alone and not on the direction of the wellbore.", "The minimum horizontal stress, which gives transverse fractures.", "The vertical, since only a vertical well produces fractures in a plane that can be predicted with any confidence."]'::jsonb, 2, 'On this fixture the stability optimum and the completion optimum happen to agree, and they need not.'),
  ('geomech', 'intermediate', 'final', null, 26, 'Track the failure position from vertical through to horizontal on a northerly bearing.', '["Walks steadily from 150 degrees round to 90 as the inclination rises.", "Stays fixed at ninety degrees.", "Jumps discontinuously at about forty-five degrees, where the axial stress overtakes the hoop stress as the largest.", "Rotates by exactly the inclination, so a sixty degree hole has a breakout sixty degrees from its vertical position."]'::jsonb, 0, 'On a horizontal hole a breakout at ninety degrees from the high side is on the FLANK rather than the roof.'),
  ('geomech', 'intermediate', 'final', null, 27, 'Two holes fail, one on the roof and one on the flank. Why is that not the same problem?', '["It changes the caliper reading only.", "Roof material falls into the hole and flank material forms a bed on the low side.", "A flank breakout is invisible to a four-arm caliper, which measures across two orthogonal axes and misses the sides.", "A roof breakout weakens the hole against the weight of the drill string, which lies on the low side of a deviated hole."]'::jsonb, 1, 'The hole cleaning problem and the stability problem interact, and where the failure is decides how.'),
  ('geomech', 'intermediate', 'final', null, 28, 'A breakout is logged on a sixty degree hole. Can you read the stress azimuth off it directly?', '["Yes, the same way as on a vertical well.", "Yes, provided the hole is within thirty degrees of vertical, beyond which the rotation becomes too large to ignore.", "No, because breakouts do not form at a consistent angle on a deviated hole and carry no orientation information at all.", "No. Recovering a stress azimuth needs the full rotation, the inclination, the azimuth and a magnitude model."]'::jsonb, 3, 'Plenty of stress interpretations have applied the vertical-well rule to deviated data, and they are wrong by the rotation.'),
  ('geomech', 'intermediate', 'final', null, 29, 'The reference outputs this course checks against were produced how?', '["The engine itself, recorded once and reviewed.", "Published worked examples from the rock mechanics literature, converted into SI units and resampled onto a common grid.", "An independent numpy implementation of the same specification.", "Field measurements from a set of offset wells in the same basin, averaged and smoothed onto the profile''s depth samples."]'::jsonb, 2, 'Same rotations, same formulas, same criterion, same bisections on the same theta grid.'),
  ('geomech', 'intermediate', 'final', null, 30, 'Two codes written from one specification match. What have you learned, and what have you not?', '["It catches transcription, convention and specification errors, and misses a wrong equation or a wrong parameter.", "It catches everything except numerical noise.", "It catches errors in the physics and misses errors in the numerics, which is why closed forms are also needed as a check.", "It catches nothing useful, since two implementations of the same specification will always agree by construction."]'::jsonb, 0, 'If the equations are wrong, both are wrong together and the comparison is silent.'),
  ('geomech', 'intermediate', 'final', null, 31, 'Verification and validation differ how?', '["They are two names for the same activity.", "Verification asks whether the equations were solved correctly; validation asks whether they describe the world.", "Verification is done before release and validation afterwards, though both compare against the same reference data set.", "Verification uses synthetic cases and validation uses field data, and both establish that the model is fit for its purpose."]'::jsonb, 1, 'Two implementations agreeing is strong verification and no validation at all.'),
  ('geomech', 'intermediate', 'final', null, 32, 'Compare the code against the paper arithmetic on the straight-hole case. How well do they sit?', '["To within a relative tolerance of 1e-6.", "To within a few pascals, which is the accumulated rounding of the sixty bisection steps the collapse search performs.", "To within one percent, which is the acceptance criterion the golden file states for the closed-form comparison.", "Exactly, on both pressures, to the last digit."]'::jsonb, 3, 'A closed form says the program agrees with the mathematics rather than with another program.'),
  ('geomech', 'intermediate', 'final', null, 33, 'Write the vertical closed-form collapse pressure.', '["Pore pressure plus UCS divided by q.", "Three times the effective minimum stress less the effective maximum, less the strength, added to the pore pressure.", "Pore pressure plus three times effective SHmax less effective Shmin less UCS, all over one plus q.", "The effective overburden divided by the frictional ratio, plus the pore pressure and the unconfined compressive strength."]'::jsonb, 2, 'One plus q is the amplification: the largest wall stress falls by one and the smallest rises by one per unit of pressure.'),
  ('geomech', 'intermediate', 'final', null, 34, 'And the vertical closed-form fracture initiation pressure?', '["Pore pressure plus three times effective Shmin less effective SHmax, plus the tensile strength.", "The minimum horizontal stress plus the tensile strength.", "Pore pressure plus three times the effective maximum stress less the effective minimum, over one plus the frictional ratio.", "The overburden less the pore pressure, multiplied by the ratio of horizontal to vertical effective stress at that depth."]'::jsonb, 0, 'No amplification here: the least wall stress falls one for one with the well pressure.'),
  ('geomech', 'intermediate', 'final', null, 35, 'Why does the collapse search scan before it bisects?', '["Because the scan is faster than a bisection.", "Because the worst Mohr-Coulomb margin is not monotone in the well pressure.", "Because the collapse pressure can be zero, and a bisection cannot bracket a root at the very edge of its search range.", "Because the theta sweep has to be repeated at each scan step, which the bisection reuses to save computation."]'::jsonb, 1, 'A naive bisection on a non-monotone function can converge on the second crossing and report an inverted window.'),
  ('geomech', 'intermediate', 'final', null, 36, 'What makes the margin stop falling at high well pressure?', '["The rock strength rises with confinement.", "The hoop stress reaches the tensile strength, at which point the fracture criterion takes over from the shear one.", "The theta sweep finds a different worst angle whose margin behaves differently with respect to pressure.", "The radial stress becomes the largest wall stress, so raising the pressure opens the gap again."]'::jsonb, 3, 'Past the crossing the roles swap: the radial stress is sigma1 and the hoop stress is sigma3.'),
  ('geomech', 'intermediate', 'final', null, 37, 'The solver always runs the same number of halvings. Defend that design choice.', '["Speed, since a fixed count avoids a test each loop.", "Accuracy, because a fixed count always converges further than a tolerance-based loop that stops at the first success.", "Reproducibility. A fixed count gives the same bits every time.", "Robustness, because a tolerance loop can fail to terminate when the function is flat in the neighbourhood of the root."]'::jsonb, 2, 'That is what makes the oracle comparison meaningful at 1e-9 rather than at 1e-6.'),
  ('geomech', 'intermediate', 'final', null, 38, 'An equivalent mud weight table shows a collapse value far below the density of water. What is it?', '["The numerical residue of a collapse pressure of zero, meaning the criterion does not bind at that depth.", "An error in the calculation.", "A negative effective stress, which indicates the rock at that depth is already in tension before any mud is applied.", "The pore pressure gradient, which the engine substitutes for the collapse gradient when the two cannot be distinguished."]'::jsonb, 0, 'Reading it as very strong rock is right; reading it as a mud weight to use is not.'),
  ('geomech', 'intermediate', 'final', null, 39, 'And a collapse pressure above the fracture pressure at the same depth?', '["A strong rock in a weak stress field.", "The window has closed there, and the value is a flag rather than a pressure.", "A numerical failure of the scan, which has found the second crossing rather than the first and should be re-run.", "A normal result at shallow depth, where the fracture gradient is low and the collapse gradient has not yet fallen."]'::jsonb, 1, 'The mud window walk detects it, records the shallowest such depth and returns a warning naming it.'),
  ('geomech', 'intermediate', 'final', null, 40, 'You have been handed two gradients. What is the very first thing to test, and why that?', '["Is the answer sensitive to the Poisson ratio?", "Does the vertical closed form agree, since it is the cheapest of the five and catches the widest range of errors?", "Which lower-bound candidate binds, since that determines which of the remaining checks are worth running at all.", "Is the window positive, because if it is not, none of the later checks matters."]'::jsonb, 3, 'Each check is cheaper than the one after it, and each that fails makes the later ones pointless.'),
  ('geomech', 'intermediate', 'final', null, 41, 'A stability report gives two bounds and nothing else. What is missing?', '["The engine version and the run date.", "The full theta sweep at the tightest depth, without which the breakout width cannot be estimated by the reader.", "Both lower-bound candidates separately, the clamp count, the quality score and a sensitivity band.", "A three-dimensional visualisation of the wall stress state, which is what makes the failure mechanism legible."]'::jsonb, 2, 'Six columns rather than two, and the difference between a number and a usable number.'),
  ('geomech', 'intermediate', 'final', null, 42, 'Somebody asks what wellbore stability comes down to. Give them one sentence.', '["The mud weight is bounded below by shear failure or the pore pressure, and above by tension at the wall.", "A hole in rock is a stress raiser.", "The Kirsch solution gives the wall stresses as a function of the angle round the circumference of a circular opening.", "Two implementations agreeing on the same specification is verification rather than validation of the underlying model."]'::jsonb, 0, 'And all three of those depend on where the hole is pointing.');
